from urllib.parse import urlsplit, urlunsplit, parse_qsl


def apply_rewrite_rules(rules, urls):
    """
    rules: ルール辞書の順序付きリスト
    urls: URL文字列のリスト

    戻り値:
        書き換え後のURLのリスト。
        block に該当したURLは None。
    """

    def host_matches(host, match_value):
        if host is None:
            return False

        host = host.lower()
        match_value = match_value.lower()

        if match_value.startswith("*."):
            base_domain = match_value[2:]
            # ドメインそのものは除外し、厳密なサブドメインだけを許可
            return host.endswith("." + base_domain) and host != base_domain

        return host == match_value

    def replace_host(parsed, new_host):
        """
        ホストだけを置き換え、ユーザー情報とポートは維持する。
        """
        netloc = parsed.netloc

        # ユーザー情報を分離
        if "@" in netloc:
            userinfo, hostport = netloc.rsplit("@", 1)
            userinfo += "@"
        else:
            userinfo = ""
            hostport = netloc

        # 既存ポートを分離
        port = ""
        if hostport.startswith("["):
            # IPv6形式
            closing = hostport.find("]")
            if closing != -1:
                if hostport[closing + 1:].startswith(":"):
                    port = hostport[closing + 1:]
        elif ":" in hostport:
            _, port_number = hostport.rsplit(":", 1)
            if port_number.isdigit():
                port = ":" + port_number

        # IPv6アドレスを指定された場合に備えて括弧を付ける
        if ":" in new_host and not new_host.startswith("["):
            new_host = f"[{new_host}]"

        new_netloc = userinfo + new_host + port
        return parsed._replace(netloc=new_netloc)

    def rewrite_one(url):
        parsed = urlsplit(url)

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            matched = False

            if match_type == "path_prefix":
                matched = parsed.path.startswith(match_value)

            elif match_type == "host":
                matched = host_matches(parsed.hostname, match_value)

            elif match_type == "query_param":
                params = parse_qsl(
                    parsed.query,
                    keep_blank_values=True,
                )
                matched = any(name == match_value for name, _ in params)

            if not matched:
                continue

            # 最初に適合したルールだけを処理
            if action == "block":
                return None

            action_value = rule["action_value"]

            if action == "strip_prefix":
                path = parsed.path
                if path.startswith(action_value):
                    path = path[len(action_value):]
                if path == "":
                    path = "/"

                parsed = parsed._replace(path=path)

            elif action == "redirect_host":
                parsed = replace_host(parsed, action_value)

            elif action == "add_query_param":
                if parsed.query:
                    query = parsed.query + "&" + action_value
                else:
                    query = action_value

                parsed = parsed._replace(query=query)

            return urlunsplit(parsed)

        # どのルールにも適合しなかった場合
        return url

    return [rewrite_one(url) for url in urls]
